<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim Merkezi V8</title>
<style>
:root{color-scheme:dark;--bg:#040812;--p:#0b1525;--p2:#101e33;--l:#263c5c;--t:#eef6ff;--m:#91a8c5;--g:#42e1a0;--b:#62a8ff;--r:#ff6b7d;--y:#ffd166;--v:#ba8cff;--s:0 16px 50px #0009;--tickerDur:220s}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#12305a 0,transparent 32%),radial-gradient(circle at 92% 0,#321b58 0,transparent 28%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}button,input,select{font:inherit}.shell{max-width:2300px;margin:auto}.top{position:sticky;top:5px;z-index:30;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--l);border-radius:16px;background:#081322ef;box-shadow:var(--s)}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px;font-weight:500}.status,.tabs,.tags,.row,.legend{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.status{justify-content:flex-end}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.hidden{display:none!important}.login{max-width:440px;margin:10vh auto;padding:24px;border:1px solid var(--l);border-radius:18px;background:var(--p);box-shadow:var(--s)}button{cursor:pointer;border:0;border-radius:8px;padding:8px 11px;background:var(--g);color:#032018;font-weight:900}button:disabled{opacity:.42;cursor:not-allowed}.secondary{background:#203653;color:var(--t)}.danger{background:var(--r);color:#fff}.small{font-size:9px;padding:6px 8px}.full{width:100%;margin-top:9px}.tabs{margin:11px 0}.tab{background:#0a1628;color:var(--m);border:1px solid var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.ticker{display:flex;align-items:center;overflow:hidden;border:1px solid #755b25;background:linear-gradient(90deg,#21170b,#191424,#21170b);border-radius:11px;margin:10px 0;white-space:nowrap}.tickerViewport{overflow:hidden;flex:1}.tickerTrack{display:inline-block;padding:9px 0;animation:ticker var(--tickerDur) linear infinite;font-size:10px;font-weight:800;color:var(--y);will-change:transform}.ticker:hover .tickerTrack,.ticker.paused .tickerTrack{animation-play-state:paused}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.ticker button{margin:4px;flex:none;padding:5px 8px;background:#2b2111;color:var(--y);border:1px solid #765d2a}.metrics{display:grid;grid-template-columns:repeat(8,minmax(120px,1fr));gap:8px}.metric,.item{padding:10px;border:1px solid var(--l);border-radius:11px;background:linear-gradient(180deg,var(--p2),#091423)}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:6px;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.panel{display:none;gap:10px}.panel.active{display:grid}.card{padding:12px;border:1px solid var(--l);border-radius:14px;background:linear-gradient(180deg,#101b2eeb,#08101deb);box-shadow:var(--s);overflow:hidden}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:9px}.title h2{margin:0;font-size:15px}.item h3{margin:0 0 4px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.row{justify-content:space-between}label{display:block;color:var(--m);font-size:9px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:end;margin-top:8px}.tablewrap{overflow:auto;max-height:700px;overscroll-behavior:contain;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1100px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l);z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right}.bar{height:7px;background:#152239;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.event,.tx,.news{padding:8px 0;border-bottom:1px solid var(--l);font-size:9px}.tx{display:grid;grid-template-columns:55px 120px 1fr auto;gap:7px}.news strong{font-size:11px}.chart{width:100%;height:240px;border:1px solid var(--l);border-radius:10px;background:#060d19}.sw{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:4px}.score{font-size:38px;font-weight:1000}.score.a{color:var(--g)}.score.b{color:var(--b)}.score.c{color:var(--y)}.score.d{color:var(--r)}.busy{position:fixed;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--g),var(--b),var(--v));transform:scaleX(0);transform-origin:left;z-index:100}.busy.on{transform:scaleX(1)}#toast{position:fixed;right:12px;bottom:12px;max-width:520px;z-index:90;background:#10243b;box-shadow:var(--s)}.notice,.banner{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.banner{border-color:#6d592b;color:var(--y);background:#211d12}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.search{max-width:600px}.filterbar{display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;margin:8px 0}@media(max-width:1600px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:950px){body{padding:5px}.top{position:static;flex-direction:column;align-items:flex-start}.status{justify-content:flex-start}.metrics{grid-template-columns:repeat(2,1f