</style></head><body><div id="busy" class="busy"></div><div class="shell"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V8<small>Kararlı oturum · adil ceza · 500 hizmet · 200 kategori · kalıcı ticari yönetim</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">MOTOR KONTROL EDİLİYOR</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Giriş</b></span><span class="pill">Son veri <b id="updated">—</b></span><button id="logout" class="secondary small hidden">Çıkış</button></div></header><section id="loginView" class="login"><h1>Şirket hesabına giriş</h1><p class="sub">Giriş yapılmadan canlı yönetim isteği gönderilmez; sayfa kendini yenilemez.</p><label>Kullanıcı adı<input id="username" autocomplete="username"></label><label>Parola<input id="password" type="password" autocomplete="current-password"></label><button id="login" class="full">Giriş yap</button><div id="loginMsg" class="notice">Motor bağlantısı kontrol ediliyor…</div></section><main id="app" class="hidden"><div id="tickerBox" class="ticker"><button id="tickerPause">⏸</button><div class="tickerViewport"><div id="ticker" class="tickerTrack">Haber bülteni hazırlanıyor…</div></div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"><button class="tab active" data-panel="overview">Genel</button><button class="tab" data-panel="finance">Gelir & Gider</button><button class="tab" data-panel="penalties">Cezalar & Uyum</button><button class="tab" data-panel="services">Hizmetler & Kapasite</button><button class="tab" data-panel="serviceCatalog">500 Hizmet Kataloğu</button><button class="tab" data-panel="products">Ürünler & Dağıtım</button><button class="tab" data-panel="appCatalog">200 Uygulama Kategorisi</button><button class="tab" data-panel="infra">Altyapı</button><button class="tab" data-panel="bank">Banka</button><button class="tab" data-panel="protocols">Protokoller</button><button class="tab" data-panel="contracts">SLA</button><button class="tab" data-panel="news">Haberler</button><button class="tab" data-panel="account">Hesap</button></nav><section id="overview" class="panel active"></section><section id="finance" class="panel"></section><section id="penalties" class="panel"></section><section id="services" class="panel"></section><section id="serviceCatalog" class="panel"></section><section id="products" class="panel"></section><section id="appCatalog" class="panel"></section><section id="infra" class="panel"></section><section id="bank" class="panel"></section><section id="protocols" class="panel"></section><section id="contracts" class="panel"></section><section id="news" class="panel"></section><section id="account" class="panel"></section></main></div><div id="toast" class="notice hidden"></div>
<script>
'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const PANELS=new Set(['overview','finance','penalties','services','serviceCatalog','products','appCatalog','infra','bank','protocols','contracts','news','account']);const S={d:null,auth:false,active:PANELS.has(location.hash.slice(1))?location.hash.slice(1):'overview',loading:false,busy:false,timer:null,pending:null,drafts:new Map(),filters:new Map(),toastTimer:null,lastTick:-1,scrolls:new Map(),tickerSig:'',paused:false};
const field=(k,v,t='number',a='')=>`<input data-key="${esc(k)}" type="${t}" value="${esc(S.drafts.has(k)?S.drafts.get(k):v??'')}" ${a}>`;const sel=(k,v,opts)=>{const x=String(S.drafts.has(k)?S.drafts.get(k):v??'');return `<select data-key="${esc(k)}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===x?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`};
function panel(id){id=PANELS.has(id)?id:'overview';S.active=id;$$('.panel').forEach(p=>p.classList.toggle('active',p.id===id));$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===id));$('#panelName').textContent=document.querySelector(`.tab[data-panel="${id}"]`)?.textContent||id;history.replaceState(null,'',`#${id}`);renderActive()}$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(b){e.preventDefault();panel(b.dataset.panel)}});$('#tickerPause').onclick=()=>{S.paused=!S.paused;$('#tickerBox').classList.toggle('paused',S.paused);$('#tickerPause').textContent=S.paused?'▶':'⏸'};
function editing(){return S.busy||!!document.activeElement?.matches('input,select,textarea')}function toast(t,ok=true){const e=$('#toast');clearTimeout(S.toastTimer);e.textContent=t;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');S.toastTimer=setTimeout(()=>e.classList.add('hidden'),5500)}async function req(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(r.status===401){const e=new Error(d.aciklama||'Oturum bulunamadı.');e.session=true;throw e}if(!r.ok||d.basarili===false)throw new Error(d.aciklama||`HTTP ${r.status}`);return d}
function saveScroll(){const p=document.getElementById(S.active);if(!p)return;S.scrolls.set(`window:${S.active}`,window.scrollY);p.querySelectorAll('[data-scroll-key]').forEach(e=>S.scrolls.set(`${S.active}:${e.dataset.scrollKey}`,e.scrollTop))}function restoreScroll(){requestAnimationFrame(()=>{window.scrollTo(0,S.scrolls.get(`window:${S.active}`)||0);document.querySelectorAll(`#${CSS.escape(S.active)} [data-scroll-key]`).forEach(e=>{const k=`${S.active}:${e.dataset.scrollKey}`;if(S.scrolls.has(k))e.scrollTop=S.scrolls.get(k)})})}
function showLogin(msg='Şirket hesabınızla giriş yapın.'){S.auth=false;clearInterval(S.timer);S.timer=null;S.pending=null;$('#app').classList.add('hidden');$('#logout').classList.add('hidden');$('#loginView').classList.remove('hidden');$('#loginMsg').textContent=msg;$('#loginMsg').className='notice';$('#panelName').textContent='Giriş'}function showApp(){S.auth=true;$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');panel(S.active)}async function login(){const b=$('#login');b.disabled=true;try{const r=await req('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();toast(r.aciklama);await refresh(true);poll()}catch(e){showLogin(e.message);$('#loginMsg').className='notice bad'}finally{b.disabled=false}}async function logout(){try{await req('/api/cikis',{})}catch{}showLogin('Çıkış yapıldı.')}function poll(){clearInterval(S.timer);if(S.auth)S.timer=setInterval(()=>refresh(false),1200)}async function health(){try{const r=await req('/api/saglik');$('#dot').classList.add('ok');$('#conn').textContent=`MOTOR HAZIR · ${r.katalogHizmeti||500} HİZMET`;$('#loginMsg').textContent='Motor hazır. Şirket hesabınızla giriş yapın.'}catch(e){$('#dot').classList.remove('ok');$('#conn').textContent='MOTOR HATASI';$('#loginMsg').textContent=e.message;$('#loginMsg').className='notice bad'}}
async function refresh(force=false){if(!S.auth||S.loading)return;S.loading=true;try{const d=await req(`/api/durum?t=${Date.now()}`);S.d=d;const tick=Number(d.tickNumarasi||d.muhasebeV7?.sonTick?.tickNumarasi||0);$('#dot').classList.add('ok');$('#conn').textContent='CANLI';$('#tick').textContent=int(tick);$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');renderMetrics(d);renderTicker(d);if(force||tick!==S.lastTick){if(editing())S.pending=d;else{S.pending=null;saveScroll();renderActive();restoreScroll();S.lastTick=tick}}else if(S.pending&&!editing()){S.d=S.pending;S.pending=null;saveScroll();renderActive();restoreScroll()}}catch(e){if(e.session){showLogin('Oturum süresi doldu. Lütfen yeniden giriş yapın.');return}$('#dot').classList.remove('ok');$('#conn').textContent='VERİ HATASI';toast(e.message,false)}finally{S.loading=false}}
function latest(d){return d.muhasebeV7?.sonTick||{}}function renderMetrics(d){const s=d.sirket||{},i=d.isletim||{},m=latest(d),b=d.bankaV7||{},v=d.v6Sirket||{},c=d.cezaV8||{};const a=[['Kasa',money(s.kasa)],['Tick gelir',money(m.toplamGelir)],['Tick gider',money(m.toplamGider)],['Tick net',money(m.tickNetKazanc)],['Tick ceza',money(c.buTickUygulananCeza)],['Affedilen',money(c.buTickAffedilenCeza)],['Kredi notu',`${int(b.krediNotu)} · ${esc(b.krediNotuSinifi||'—')}`],['Toplam borç',money(b.aktifBorc)],['Gerçek kapasite',int(v.gercekKapasiteBirimi)],['Kullanılan kapasite',int(v.kullanilanKapasiteBirimi)],['Aktif kullanıcı',int(i.toplamAboneSayisi)],['Şirket değeri',money(i.sirketDegeri)]];$('#metrics').innerHTML=a.map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}function renderTicker(d){const h=(d.haberBulteni||[]).slice(0,12),text=h.length?h.map(x=>`★ T${int(x.tickNumarasi)} · ${esc(x.sirketAdi||'Piyasa')} · ${esc(x.baslik)} — ${esc(x.ozet)}`).join(' &nbsp;&nbsp;&nbsp; ◆ &nbsp;&nbsp;&nbsp; '):'★ Şirket operasyonları normal seyrediyor.',sig=text.replace(/<[^>]+>/g,'');if(sig===S.tickerSig)return;S.tickerSig=sig;const sec=Math.max(150,Math.min(420,Math.ceil(sig.length/7)));$('#tickerBox').style.setProperty('--tickerDur',`${sec}s`);$('#ticker').innerHTML=text}
function overview(d){const s=d.sirket||{},i=d.isletim||{},m=latest(d),b=d.bankaV7||{},v=d.v6Sirket||{},c=d.cezaV8||{},events=(i.sonOlaylar||[]).slice(0,12).map(o=>`<div class="event"><div class="row"><b class="${o.olumlu?'good':'bad'}">${esc(o.baslik)}</b><span>T${int(o.tickNumarasi)}</span></div><p>${esc(o.aciklama)}</p></div>`).join('')||'<div class="notice">Olay yok.</div>';return `<div class="grid"><div class="card"><div class="title"><h2>Bu tickin özeti</h2><span class="tag ${Number(m.tickNetKazanc)>=0?'good':'bad'}">${money(m.tickNetKazanc)}</span></div><div class="grid4">${[['Brüt gelir',money(m.toplamGelir)],['Toplam gider',money(m.toplamGider)],['Tick ceza',money(c.buTickUygulananCeza)],['Ceza affı',money(c.buTickAffedilenCeza)],['Nakit değişimi',money(m.nakitDegisimi)],['Kapanış kasası',money(m.kapanisKasasi)],['Borç',money(m.toplamBorc)],['Kapasite doluluğu',`%${num((v.kapasiteDolulukOrani||0)*100)}`]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Banka sağlığı</h2><span class="tag">${esc(b.riskDurumu||'—')}</span></div><div class="row"><div><div class="score ${(b.krediNotu||0)>=760?'a':(b.krediNotu||0)>=620?'b':(b.krediNotu||0)>=500?'c':'d'}">${int(b.krediNotu)}</div><p>Sınıf ${esc(b.krediNotuSinifi||'—')}</p></div><div><b>${money(b.kullanilabilirLimit)}</b><p>Kullanılabilir kredi limiti</p><b>${money(b.sonrakiTaksit)}</b><p>Sonraki taksit · T${int(b.sonrakiOdemeTicki)}</p></div></div></div></div><div class="grid"><div class="card"><div class="title"><h2>Son şirket olayları</h2></div>${events}</div><div class="card"><div class="title"><h2>Teknik ve ticari durum</h2></div><div class="grid4">${[['Kod kalitesi',num(s.kodKalitesiPuani)],['Performans',num(s.performansPuani)],['Güvenlik',num(s.guvenlikPuani)],['İtibar',num(s.itibarPuani)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ekosistem',num(i.ekosistemPuani)],['Tarihsel ceza',money(c.tarihselToplamCeza)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function svgChart(rows){if(!rows.length)return'<div class="notice">Henüz tick geçmişi yok.</div>';const w=900,h=220,p=25,vals=rows.flatMap(x=>[Number(x.toplamGelir||0),Number(x.toplamGider||0),Number(x.tickNetKazanc||0)]),max=Math.max(1,...vals.map(Math.abs)),pts=key=>rows.map((x,i)=>`${p+i*(w-2*p)/Math.max(1,rows.length-1)},${h/2-Number(x[key]||0)*(h/2-p)/max}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="0" y1="${h/2}" x2="${w}" y2="${h/2}" stroke="#33445d"/><polyline fill="none" stroke="#42e1a0" stroke-width="3" points="${pts('toplamGelir')}"/><polyline fill="none" stroke="#ff6b7d" stroke-width="3" points="${pts('toplamGider')}"/><polyline fill="none" stroke="#62a8ff" stroke-width="3" points="${pts('tickNetKazanc')}"/></svg><div class="legend"><span><i class="sw" style="background:#42e1a0"></i>Gelir</span><span><i class="sw" style="background:#ff6b7d"></i>Gider</span><span><i class="sw" style="background:#62a8ff"></i>Net</span></div>`}
function finance(d){const m=latest(d),rows=(d.muhasebeV7?.tickler||[]).slice(-60);return `<div class="card"><div class="title"><div><h2>Tick gelir–gider grafiği</h2><span class="sub">Kredi girişi gelir sayılmaz.</span></div></div>${svgChart(rows)}</div><div class="grid"><div class="card"><div class="title"><h2>Bu tick gelirleri</h2><b class="good">${money(m.toplamGelir)}</b></div>${[['Hizmet, SLA ve olay',m.hizmetSlaVeOlayGeliri],['Ürün geliri',m.urunGeliri],['Abonelik geliri (bilgi)',m.abonelikGeliriBilgi],['Protokol lisansı',m.protokolGeliri]].map(x=>`<div class="row item"><span>${x[0]}</span><b class="good">${money(x[1])}</b></div>`).join('')}</div><div class="card"><div class="title"><h2>Bu tick giderleri</h2><b class="bad">${money(m.toplamGider)}</b></div>${[['Operasyon ve altyapı',m.operasyonGideri],['Finansman/taksit',m.finansmanGideri],['Yatırım ve yayın',m.yatirimGideri],['İade/chargeback',m.iadeGideri],['Ceza',m.cezaGideri],['Yeni ödenemeyen gider',m.odenemeyenGiderArtisi]].map(x=>`<div class="row item"><span>${x[0]}</span><b class="bad">${money(x[1])}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Tick muhasebe defteri</h2><span class="tag">Son ${rows.length} tick</span></div><div class="tablewrap" data-scroll-key="finance"><table><thead><tr><th>Tick</th><th class="num">Gelir</th><th class="num">Gider</th><th class="num">Net</th><th class="num">Nakit</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Not</th></tr></thead><tbody>${[...rows].reverse().map(x=>`<tr><td>T${int(x.tickNumarasi)}</td><td class="num good">${money(x.toplamGelir)}</td><td class="num bad">${money(x.toplamGider)}</td><td class="num ${Number(x.tickNetKazanc)>=0?'good':'bad'}"><b>${money(x.tickNetKazanc)}</b></td><td class="num">${money(x.nakitDegisimi)}</td><td class="num">${money(x.kapanisKasasi)}</td><td class="num">${money(x.toplamBorc)}</td><td class="num">${int(x.krediNotu)}</td></tr>`).join('')}</tbody></table></div></div>`}
function penalties(d){const c=d.cezaV8||{};return `<div class="banner"><b>ADİL CEZA V8</b> · Motor/istek sözleşmesi kusuru şirkete yazılmaz. İlk iki gerçek tekrar uyarıdır; normal finansal ceza tickte ${money(c.tickCezaTavani||75)} ile sınırlıdır.</div><div class="metrics">${[['Tarihsel ceza',money(c.tarihselToplamCeza)],['Tick uygulanan',money(c.buTickUygulananCeza)],['Tick affedilen',money(c.buTickAffedilenCeza)],['V8 uygulanan',money(c.v8ToplamUygulananCeza)],['V8 affedilen',money(c.v8ToplamAffedilenCeza)],['Şirket kusuru',int(c.sirketKusuruSayisi)],['Motor/sözleşme',int(c.motorVeyaSozlesmeKusuruSayisi)],['Tick olay',int(c.buTickOlaySayisi)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="grid"><div class="card"><div class="title"><h2>Ceza nedenleri</h2></div>${(c.nedenler||[]).map(n=>`<div class="item row"><div><b>${esc(n.kategori)}</b><p>${int(n.olaySayisi)} olay</p></div><div><b class="bad">${money(n.uygulananCeza)}</b><p class="good">Affedilen ${money(n.affedilenCeza)}</p></div></div>`).join('')||'<div class="notice">Henüz V8 ceza kaydı yok.</div>'}</div><div class="card"><div class="title"><h2>Son ceza kayıtları</h2></div><div class="tablewrap" data-scroll-key="penalties"><table><thead><tr><th>Tick</th><th>Hizmet</th><th>Kategori</th><th>Kusur</th><th class="num">Uygulanan</th><th class="num">Affedilen</th><th>Açıklama</th></tr></thead><tbody>${(c.sonKayitlar||[]).map(x=>`<tr><td>T${int(x.tickNumarasi)}</td><td>${esc(x.hizmetKimligi)}</td><td>${esc(x.kategori)}</td><td class="${x.sirketKusuru?'bad':'good'}">${x.sirketKusuru?'ŞİRKET':'MOTOR/SÖZLEŞME'}</td><td class="num bad">${money(x.uygulananCeza)}</td><td class="num good">${money(x.affedilenCeza)}</td><td>${esc(x.aciklama)}</td></tr>`).join('')||'<tr><td colspan="7">Kayıt yok.</td></tr>'}</tbody></table></div></div></div>`}
function serviceList(){return S.d?.kodTabanliYayinlar?.hizmetler||[]}function services(d){const hs=serviceList();return `<div class="card"><div class="title"><div><h2>Kalıcı hizmet fiyatı ve kapasite tahsisi</h2><span class="sub">Sunucu manifesti ilk varsayılandır; 8090 kaydı üstün kalır.</span></div></div><div class="tablewrap" data-scroll-key="services"><table><thead><tr><th>Hizmet</th><th>Durum</th><th class="num">Fiyat</th><th class="num">Baz</th><th class="num">Satın</th><th class="num">Yatırım</th><th class="num">Etkin</th><th>İşlem</th></tr></thead><tbody>${hs.map(h=>{const id=`${h.hizmetKimligi}@${h.hizmetSurumu}`;return `<tr><td><b>${esc(h.hizmetKimligi)}</b><div class="sub">v${esc(h.hizmetSurumu)}</div></td><td class="${h.aktif?'good':'bad'}">${h.aktif?'AKTİF':'PASİF'}</td><td class="num">${field(`svc:${id}:price`,h.birimFiyat,'number','min="0.01"')}</td><td class="num">${int(h.bazKapasite)}</td><td class="num">${int(h.satinAlinanKapasite)}</td><td class="num">${int(h.yatirimKapasiteBonusu)}</td><td class="num"><b>${int(h.etkinKapasite)}</b></td><td><button class="small" data-action="service-price" data-id="${esc(id)}">Fiyat</button> <button class="small secondary" data-action="service-toggle" data-id="${esc(id)}">${h.aktif?'Kapat':'Aç'}</button><div class="row"><span>${field(`svc:${id}:cap`,1,'number','min="1" max="500"')}</span><button class="small" data-action="service-cap" data-id="${esc(id)}">Tahsis al</button></div></td></tr>`}).join('')}</tbody></table></div></div>`}
function serviceCatalog(d){const k=d.standartHizmetKatalogu||{},q=String(S.filters.get('svcq')||'').toLowerCase(),family=String(S.filters.get('svcf')||''),own=String(S.filters.get('svco')||'all');let rows=k.hizmetler||[];rows=rows.filter(x=>(!q||`${x.hizmetKimligi} ${x.aciklama}`.toLowerCase().includes(q))&&(!family||x.hizmetAilesi===family)&&(own==='all'||(own==='owned'&&x.sirketSahip)||(own==='missing'&&!x.sirketSahip)));return `<div class="metrics">${[['Motor hizmeti',int(k.toplam)],['Sahip olunan',int(k.sirketinSahipOldugu)],['Aktif sunulan',int(k.sirketinAktifSundugu)],['Uygulamada kullanılan',int(k.uygulamalardaKullanilan)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="card"><div class="title"><div><h2>500 standart hizmet kataloğu</h2><span class="sub">Bu panel yalnız motorun tanıdığı hizmetleri ve şirketinizdeki karşılığını gösterir.</span></div><span class="tag">${int(rows.length)} sonuç</span></div><div class="filterbar"><input data-filter="svcq" value="${esc(S.filters.get('svcq')||'')}" placeholder="Hizmet veya açıklama ara"><select data-filter="svcf"><option value="">Tüm aileler</option>${(k.aileler||[]).map(x=>`<option value="${esc(x.aile)}" ${family===x.aile?'selected':''}>${esc(x.aile)} · ${int(x.sahip)}/${int(x.toplam)}</option>`).join('')}</select><select data-filter="svco"><option value="all" ${own==='all'?'selected':''}>Tümü</option><option value="owned" ${own==='owned'?'selected':''}>Sahip olduklarım</option><option value="missing" ${own==='missing'?'selected':''}>Eksikler</option></select></div><div class="tablewrap" data-scroll-key="serviceCatalog"><table><thead><tr><th>Hizmet</th><th>Aile</th><th>Açıklama</th><th>Sahiplik</th><th class="num">Fiyat</th><th class="num">Kapasite</th><th class="num">Uygulama</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.hizmetKimligi)}</b><div class="sub">v${esc(x.hizmetSurumu)}</div></td><td>${esc(x.hizmetAilesi)}</td><td>${esc(x.aciklama)}</td><td class="${x.sirketSahip?'good':'bad'}">${x.sirketSahip?(x.sirketAktif?'AKTİF':'PASİF'):'YOK'}</td><td class="num">${x.sirketSahip?money(x.sirketFiyati):'—'}</td><td class="num">${x.sirketSahip?int(x.sirketKapasitesi):'—'}</td><td class="num">${int(x.uygulamaKullanimi)}</td></tr>`).join('')}</tbody></table></div></div>`}
function distributionMap(d){return new Map((d.ekosistem?.dagitimAyarlari||[]).map(x=>[x.urunKimligi,x.ayar||{}]))}function osOptions(d){return [['','İşletim sistemi seç']].concat((d.ekosistem?.isletimSistemleri||[]).map(x=>[x.uygulamaKimligi,`${x.uygulamaAdi} · ${x.sirketAdi}`]))}function protocolOptions(d){const own=(d.kodTabanliYayinlar?.protokoller||[]).filter(x=>x.piyasada).map(x=>[x.protokol?.protokolKimligi,`${x.protokol?.protokolAdi} (kendi)`]),market=(d.protokoller||[]).map(x=>[x.protokolKimligi,`${x.protokolAdi} (piyasa)`]);return [...new Map([['','Protokol seç'],...own,...market]).entries()]}
function products(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],ps=d.isletim?.urunler||[],dm=distributionMap(d),os=osOptions(d),protos=protocolOptions(d);return `<div class="card"><div class="title"><h2>Kodlanan ürünler</h2></div>${apps.map(x=>appCard(x)).join('')||'<div class="notice">Manifest yok.</div>'}</div><div class="card"><div class="title"><h2>Piyasadaki ürünler ve dağıtım</h2></div>${ps.map(p=>productCard(p,dm.get(p.urunKimligi)||{},os,protos)).join('')||'<div class="notice">Ürün yok.</div>'}</div>`}function appCard(x){const a=x.uygulama||{},v=x.dogrulama||{},id=a.uygulamaKimligi;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(a.uygulamaAdi)} <span class="tag">${esc(a.kategori)}</span></h3><p>${esc(a.aciklama)}</p></div><span class="tag ${v.gecerli?'good':'bad'}">${v.gecerli?'GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Model${sel(`app:${id}:model`,'abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans']])}</label><label>Abonelik${field(`app:${id}:sub`,25,'number','min="0"')}</label><label>Kullanım${field(`app:${id}:use`,0,'number','min="0"')}</label><button data-action="app-publish" data-id="${esc(id)}" ${!v.gecerli?'disabled':''}>Piyasaya aç</button></div>`}</div>`}function productCard(p,a,os,protos){const id=p.urunKimligi,isOS=p.urunTuru==='isletim-sistemi',occ=Number(p.kullaniciKapasitesi)>0?Number(p.aktifKullaniciSayisi)*100/Number(p.kullaniciKapasitesi):0;return `<div class="item" style="margin-bottom:8px"><div class="row"><div><h3>${esc(p.urunAdi)} <span class="tag">${esc(p.urunTuru||p.kategori)}</span></h3><p>${int(p.aktifKullaniciSayisi)} / ${int(p.kullaniciKapasitesi)} kullanıcı · %${num(occ)}</p></div><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'PASİF'}</span></div><div class="bar"><i style="width:${Math.min(100,occ)}%"></i></div><div class="form"><label>İşletim sistemi${isOS?'<input value="Kendisi işletim sistemi" disabled>':sel(`dist:${id}:os`,a.isletimSistemiKimligi||'',os)}</label><label>Protokol${sel(`dist:${id}:proto`,a.baglantiProtokoluKimligi||'',protos)}</label><label>Durum${sel(`dist:${id}:active`,String(a.aktifOlmasiIsteniyor??p.aktif),[['true','Aktif'],['false','Pasif']])}</label><button data-action="distribution" data-id="${esc(id)}">Dağıtımı kaydet</button></div><div class="form"><label>Abonelik${field(`prd:${id}:sub`,p.abonelikUcreti,'number','min="0"')}</label><label>Kullanım${field(`prd:${id}:use`,p.kullanimBasinaUcret,'number','min="0"')}</label><label>Tahsis ekle${field(`prd:${id}:cap`,100,'number','min="50" max="100000"')}</label><div><button class="small" data-action="product-save" data-id="${esc(id)}">Fiyat</button> <button class="small secondary" data-action="product-cap" data-id="${esc(id)}">Kapasite</button></div></div></div>`}
function appCatalog(d){const k=d.uygulamaKategoriKatalogu||{},q=String(S.filters.get('appq')||'').toLowerCase(),sector=String(S.filters.get('apps')||''),ready=String(S.filters.get('appr')||'all');let rows=k.kategoriler||[];rows=rows.filter(x=>(!q||`${x.kategoriKimligi} ${x.kategoriAdi} ${x.sektor}`.toLowerCase().includes(q))&&(!sector||x.sektor===sector)&&(ready==='all'||(ready==='ready'&&x.sirketTeknikOlarakHazir)||(ready==='missing'&&!x.sirketTeknikOlarakHazir)||(ready==='apps'&&(x.sirketUygulamalari||[]).length)));return `<div class="metrics">${[['Motor kategorisi',int(k.toplam)],['Uygulama yayımlanan',int(k.sirketinUygulamaYayinladigi)],['Teknik hazır',int(k.sirketinTeknikOlarakHazirOldugu)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="card"><div class="title"><div><h2>200 uygulama kategorisi</h2><span class="sub">Her kategori gerekli hizmetleri ve şirketinizdeki hazır olma durumunu gösterir.</span></div><span class="tag">${int(rows.length)} sonuç</span></div><div class="filterbar"><input data-filter="appq" value="${esc(S.filters.get('appq')||'')}" placeholder="Kategori, sektör veya kimlik ara"><select data-filter="apps"><option value="">Tüm sektörler</option>${(k.sektorler||[]).map(x=>`<option value="${esc(x.sektor)}" ${sector===x.sektor?'selected':''}>${esc(x.sektor)} · ${int(x.hazir)}/${int(x.kategoriSayisi)}</option>`).join('')}</select><select data-filter="appr"><option value="all" ${ready==='all'?'selected':''}>Tümü</option><option value="ready" ${ready==='ready'?'selected':''}>Teknik hazır</option><option value="missing" ${ready==='missing'?'selected':''}>Eksik hizmetli</option><option value="apps" ${ready==='apps'?'selected':''}>Uygulamam olan</option></select></div><div class="tablewrap" data-scroll-key="appCatalog"><table><thead><tr><th>Kategori</th><th>Sektör/Tür</th><th>Zorunlu hizmetler</th><th>Eksikler</th><th>Hizmet sayısı</th><th>Kapasite</th><th>Uygulamalarım</th><th>Hazır</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.kategoriAdi)}</b><div class="sub">${esc(x.kategoriKimligi)}</div></td><td>${esc(x.sektor)} · ${esc(x.urunTuru)}</td><td>${(x.zorunluHizmetler||[]).map(h=>`<span class="tag ${(x.eksikZorunluHizmetler||[]).includes(h)?'bad':'good'}">${esc(h)}</span>`).join(' ')}</td><td>${(x.eksikZorunluHizmetler||[]).map(h=>`<span class="tag bad">${esc(h)}</span>`).join(' ')||'<span class="good">Yok</span>'}</td><td>${int(x.asgariHizmetSayisi)} / ${int(x.onerilenHizmetSayisi)} / ${int(x.azamiHizmetSayisi)}</td><td>Taban ${num(x.tabanKapasiteTuketimi)} · Kullanıcı ${num(x.kullaniciBasinaKapasiteTuketimi)}</td><td>${(x.sirketUygulamalari||[]).map(a=>`<span class="tag">${esc(a.uygulamaAdi)} · ${int(a.hizmetSayisi)} hizmet</span>`).join(' ')||'—'}</td><td class="${x.sirketTeknikOlarakHazir?'good':'bad'}">${x.sirketTeknikOlarakHazir?'HAZIR':'EKSİK'}</td></tr>`).join('')}</tbody></table></div></div>`}
function infra(d){const l=d.ekosistem?.altyapiSinirlari||{},v=d.v6Sirket||{},list=d.yatirimMagazasi||[];return `<div class="card"><div class="title"><h2>Gerçek fiziksel kapasite havuzu</h2></div><div class="grid4">${[['Gerçek havuz',int(v.gercekKapasiteBirimi)],['Tahsis edilen',int(v.tahsisEdilenKapasiteBirimi)],['Anlık kullanılan',int(v.kullanilanKapasiteBirimi)],['Doluluk',`%${num((v.kapasiteDolulukOrani||0)*100)}`],['İşlem sınırı',int(l.eszamanliIslemSiniri)],['Uygulama sınırı',int(l.uygulamaKullaniciSiniri)],['Ağ sınırı',int(l.agAktarimSiniri)],['Depolama sınırı',int(l.depolamaSiniri)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Yatırım mağazası</h2></div><div class="grid3">${list.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.aciklama)}</p><p>Mevcut ${int(x.mevcutSeviye)} · Sonraki maliyet ${money(x.sonrakiMaliyet)}</p><button class="full" data-action="investment" data-id="${esc(x.yatirimTuru)}" ${x.satinAlinabilir===false?'disabled':''}>Yatırım başlat</button></div>`).join('')||'<div class="notice">Yatırım paketi yok.</div>'}</div></div>`}
function bank(d){const b=d.bankaV7||{},packs=d.krediPaketleri||[],loans=d.isletim?.krediler||[];return `<div class="grid"><div class="card"><div class="title"><h2>Kredi notu ve limit</h2><span class="tag ${Number(b.krediNotu)>=650?'good':Number(b.krediNotu)>=500?'warn':'bad'}">${esc(b.riskDurumu||'—')}</span></div><div class="row"><div class="score ${(b.krediNotu||0)>=760?'a':(b.krediNotu||0)>=620?'b':(b.krediNotu||0)>=500?'c':'d'}">${int(b.krediNotu)}</div><div><p>Toplam limit</p><b>${money(b.tahminiKrediLimiti)}</b><p>Kullanılabilir</p><b>${money(b.kullanilabilirLimit)}</b></div></div><div class="grid4">${[['Aktif borç',money(b.aktifBorc)],['Sonraki taksit',money(b.sonrakiTaksit)],['Ödeme ticki',`T${int(b.sonrakiOdemeTicki)}`],['Faiz çarpanı',`×${num(b.piyasaFaizCarpani)}`],['Aktif kredi',int(b.aktifKrediSayisi)],['Temerrüt',int(b.temerrutSayisi)],['Kurtarma kredisi',int(b.kurtarmaKredisiSayisi)],['Not sınıfı',esc(b.krediNotuSinifi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Kredi paketleri</h2></div>${packs.map(p=>`<div class="item"><h3>${esc(p.ad)}</h3><p>${money(p.asgariTutar)}–${money(p.azamiTutar)} · Not ≥ ${int(p.asgariKrediNotu)} · Tick faiz %${num(Number(p.tickFaizOrani)*100)}</p><label>Tutar${field(`loan:${p.krediTuru}`,p.asgariTutar,'number',`min="${p.asgariTutar}" max="${p.azamiTutar}"`)}</label><button class="full" data-action="loan" data-id="${esc(p.krediTuru)}">Kredi çek</button></div>`).join('')}</div></div><div class="card"><div class="title"><h2>Mevcut krediler</h2></div><div class="tablewrap"><table><thead><tr><th>Tür</th><th class="num">Ana para</th><th class="num">Kalan borç</th><th class="num">Taksit</th><th class="num">Faiz/tick</th><th class="num">Kalan taksit</th><th class="num">Sonraki tick</th><th>Durum</th></tr></thead><tbody>${loans.map(l=>`<tr><td><b>${esc(l.krediTuru)}</b></td><td class="num">${money(l.anaPara)}</td><td class="num">${money(l.kalanBorc)}</td><td class="num">${money(l.taksitTutari)}</td><td class="num">%${num(Number(l.tickFaizOrani)*100)}</td><td class="num">${int(l.kalanTaksit)}</td><td class="num">T${int(l.sonrakiOdemeTicki)}</td><td class="${l.aktif?'warn':'good'}">${l.aktif?'AKTİF':'KAPANDI'}</td></tr>`).join('')||'<tr><td colspan="8">Kredi yok.</td></tr>'}</tbody></table></div></div>`}
function protocols(d){const own=d.kodTabanliYayinlar?.protokoller||[],market=d.protokoller||[];return `<div class="grid"><div class="card"><h2>Kodlanan protokoller</h2>${own.map(x=>{const p=x.protokol||{},id=`${p.protokolKimligi}@${p.surum}`;return `<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><span class="tag ${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</span></div>${x.piyasada?'<div class="notice good">Piyasada</div>':`<div class="form"><label>Lisans${sel(`proto:${id}:model`,'acik',[['acik','Açık'],['tek-seferlik','Tek seferlik'],['abonelik','Abonelik'],['karma','Karma']])}</label><label>Benimseme${field(`proto:${id}:adopt`,0)}</label><label>Tick lisansı${field(`proto:${id}:tick`,0)}</label><button data-action="protocol-publish" data-id="${esc(id)}">Yayınla</button></div>`}</div>`}).join('')}</div><div class="card"><h2>Piyasa protokolleri</h2>${market.map(p=>`<div class="item"><div class="row"><b>${esc(p.protokolAdi)} v${esc(p.surum)}</b><button class="small" data-action="protocol-adopt" data-id="${esc(p.protokolKimligi)}">Benimse</button></div><p>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</p></div>`).join('')||'<div class="notice">Piyasa protokolü yok.</div>'}</div></div>`}
function contracts(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[],map=new Map((d.slaUygunluklari||[]).map(x=>[x.teklifKimligi,x]));return `<div class="grid"><div class="card"><div class="title"><h2>Açık SLA teklifleri</h2></div>${offers.map(o=>{const u=map.get(o.teklifKimligi)||{uygun:false,gerekliHizmetler:[],eksikHizmetler:[],yetersizKosullar:['Uygunluk hesaplanmadı']};return `<div class="item"><div class="row"><div><h3>${esc(o.baslik)}</h3><p>${esc(o.kategori)} · ${money(o.tickOdemesi)}/tick · Ceza ${money(o.ihlalCezasi)}</p></div><span class="tag ${u.uygun?'good':'bad'}">${u.uygun?'UYGUN':'UYGUN DEĞİL'}</span></div><div class="tags">${(u.gerekliHizmetler||[]).map(h=>`<span class="tag ${(u.eksikHizmetler||[]).includes(h)?'bad':'good'}">${esc(h)}</span>`).join('')}</div>${(u.yetersizKosullar||[]).length?`<div class="notice bad">${u.yetersizKosullar.map(esc).join(' · ')}</div>`:''}<div class="row"><span>Kapasite ${int(o.gerekliKapasite)} · K/P/G ${num(o.asgariKalite)}/${num(o.asgariPerformans)}/${num(o.asgariGuvenlik)}</span><button class="small" data-action="contract" data-id="${esc(o.teklifKimligi)}" ${u.uygun?'':'disabled'}>Kabul et</button></div></div>`}).join('')||'<div class="notice">Teklif yok.</div>'}</div><div class="card"><h2>Aktif sözleşmeler</h2>${active.map(s=>`<div class="item"><b>${esc(s.baslik)}</b><p>Başarı ${int(s.basariliTickSayisi)} · İhlal ${int(s.ihlalSayisi)} · Kapasite ${int(s.gerekliKapasite)} · T${int(s.bitisTicki)} bitiş</p></div>`).join('')||'<div class="notice">Sözleşme yok.</div>'}</div></div>`}
function news(d){const h=d.haberBulteni||[];return `<div class="card"><div class="title"><div><h2>Şirket haber bülteni</h2><span class="sub">Finansal alarm, kapasite, yatırım, uygulama ve piyasa olayları.</span></div></div>${h.map(x=>`<article class="news"><div class="row"><strong class="${x.seviye==='kritik'||x.onem==='kritik'?'bad':x.seviye==='iyi'||x.onem==='iyi'?'good':'warn'}">${esc(x.baslik)}</strong><span>T${int(x.tickNumarasi)}</span></div><p>${esc(x.ozet)}</p>${Number(x.finansalEtki)?`<b class="${Number(x.finansalEtki)>=0?'good':'bad'}">${money(x.finansalEtki)}</b>`:''}</article>`).join('')||'<div class="notice">Haber yok.</div>'}</div>`}function account(d){const i=d.isletim||{};return `<div class="grid"><div class="card"><h2>Parola değiştir</h2><label>Mevcut${field('account:old','', 'password')}</label><label>Yeni${field('account:new','', 'password')}</label><button class="full" data-action="password">Değiştir</button></div><div class="card"><h2>Risk özeti</h2><div class="grid4">${[['Operasyon',num(i.operasyonRiski)],['Teknik borç',num(i.teknikBorc)],['Bakım baskısı',num(i.bakimBaskisi)],['Ödenemeyen',money(i.odenemeyenGider)],['Temerrüt',int(i.temerrutSayisi)],['Kredi notu',int(i.krediNotu)],['Tarihsel gider',money(i.toplamIsletmeGideri)],['Yatırım',money(i.toplamYatirimHarcamasi)]].map(x=>`<div class="item"><p>${x[0]}</p><b>${x[1]}</b></div>`).join('')}</div></div></div>`}
function renderActive(){if(!S.auth||!S.d)return;const el=document.getElementById(S.active);if(!el)return;const fn={overview,finance,penalties,services,serviceCatalog,products,appCatalog,infra,bank,protocols,contracts,news,account}[S.active]||overview;el.innerHTML=fn(S.d)}function val(k){const e=document.querySelector(`[data-key="${CSS.escape(k)}"]`);return e?e.value:(S.drafts.get(k)??'')}function nval(k){const x=Number(val(k));if(!Number.isFinite(x))throw new Error('Sayısal değer geçersiz.');return x}function findService(id){const h=serviceList().find(x=>`${x.hizmetKimligi}@${x.hizmetSurumu}`===id);if(!h)throw new Error('Hizmet bulunamadı.');return h}function findProduct(id){const p=(S.d?.isletim?.urunler||[]).find(x=>x.urunKimligi===id);if(!p)throw new Error('Ürün bulunamadı.');return p}
async function run(b,job){if(S.busy)return;S.busy=true;$('#busy').classList.add('on');const old=b.textContent;b.disabled=true;b.textContent='İşleniyor…';try{const r=await job();toast(r.aciklama||'Tamamlandı.');await refresh(true)}catch(e){if(e.session){showLogin('Oturum süresi doldu.')}else toast(e.message,false)}finally{S.busy=false;b.disabled=false;b.textContent=old;$('#busy').classList.remove('on')}}async function action(b){const a=b.dataset.action,id=b.dataset.id||'';await run(b,async()=>{if(a==='service-price'){const h=findService(id);return req('/api/hizmet/fiyat',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,yeniFiyat:nval(`svc:${id}:price`)})}if(a==='service-toggle'){const h=findService(id);return req('/api/hizmet/durum',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,aktif:!h.aktif})}if(a==='service-cap'){const h=findService(id);return req('/api/hizmet/kapasite',{hizmetKimligi:h.hizmetKimligi,hizmetSurumu:h.hizmetSurumu,eklenecekKapasite:nval(`svc:${id}:cap`)})}if(a==='investment')return req('/api/yatirim',{yatirimTuru:id});if(a==='loan')return req('/api/kredi',{krediTuru:id,tutar:nval(`loan:${id}`)});if(a==='app-publish')return req('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:val(`app:${id}:model`),abonelikUcreti:nval(`app:${id}:sub`),kullanimBasinaUcret:nval(`app:${id}:use`)});if(a==='product-save'){const p=findProduct(id);return req('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:nval(`prd:${id}:sub`),kullanimBasinaUcret:nval(`prd:${id}:use`),aktif:p.aktif})}if(a==='product-cap')return req('/api/uygulama/kapasite',{urunKimligi:id,eklenecekKapasite:nval(`prd:${id}:cap`)});if(a==='distribution')return req('/api/uygulama/dagitim',{urunKimligi:id,isletimSistemiKimligi:val(`dist:${id}:os`),baglantiProtokoluKimligi:val(`dist:${id}:proto`),aktifOlmasiIsteniyor:val(`dist:${id}:active`)==='true'});if(a==='protocol-publish'){const [pid,sur]=id.split('@');return req('/api/protokol/yayinla',{protokolKimligi:pid,surum:sur,lisansModeli:val(`proto:${id}:model`),benimsemeBedeli:nval(`proto:${id}:adopt`),tickLisansBedeli:nval(`proto:${id}:tick`)})}if(a==='protocol-adopt')return req('/api/protokol/benimse',{protokolKimligi:id});if(a==='contract')return req('/api/sozlesme/kabul',{teklifKimligi:id});if(a==='password')return req('/api/parola',{eskiParola:val('account:old'),yeniParola:val('account:new')});throw new Error('Bilinmeyen işlem.')})}
document.addEventListener('input',e=>{const k=e.target?.dataset?.key,f=e.target?.dataset?.filter;if(k)S.drafts.set(k,e.target.value);if(f){S.filters.set(f,e.target.value);renderActive()}});document.addEventListener('change',e=>{const k=e.target?.dataset?.key,f=e.target?.dataset?.filter;if(k)S.drafts.set(k,e.target.value);if(f){S.filters.set(f,e.target.value);renderActive()}});document.addEventListener('focusout',()=>{setTimeout(()=>{if(!editing()&&S.pending){S.d=S.pending;S.pending=null;saveScroll();renderActive();restoreScroll()}},30)});document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b)});$('#login').onclick=login;$('#logout').onclick=logout;$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});showLogin();health();
</script></body></html>
""";
